INSERT INTO material(disciplina_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,contem_gabarito,autorizacao_professor) SELECT id,'estatistica_novo.pdf','Arquivo original preservado. Fonte teórica aprovada; revisão por IA identificada separadamente.','SLIDE_AULA','local:materiais_academicos/periodo_03/estatistica/estatistica_novo.pdf',TRUE,FALSE,FALSE,FALSE FROM disciplina d WHERE d.slug='estatistica' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/estatistica/estatistica_novo.pdf');
INSERT INTO material(disciplina_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,contem_gabarito,autorizacao_professor) SELECT id,'Exercissios 1 Unidade.docx','Arquivo original preservado. Autorização do professor declarada pelo usuário em 27/10/2026. Gabarito oficial não confirmado.','LISTA_EXERCICIOS','local:materiais_academicos/periodo_03/estatistica/Exercissios 1 Unidade.docx',FALSE,TRUE,TRUE,TRUE FROM disciplina d WHERE d.slug='estatistica' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/estatistica/Exercissios 1 Unidade.docx');
INSERT INTO material(disciplina_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,contem_gabarito,autorizacao_professor) SELECT id,'prova anterior de estátisitica.pdf','Arquivo original preservado. Autorização do professor declarada pelo usuário em 27/10/2026. Gabarito oficial não confirmado.','PROVA_ANTIGA','local:materiais_academicos/periodo_03/estatistica/prova anterior de estátisitica.pdf',FALSE,TRUE,FALSE,TRUE FROM disciplina d WHERE d.slug='estatistica' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/estatistica/prova anterior de estátisitica.pdf');
